:root {
  --bg-primary: #f7f9f6;
  --bg-card: #ffffff;
  --sage-dark: #3b5249;
  --sage-mid: #587b6d;
  --sage-light: #e3ebd9;
  --cream: #f4f1ea;
  --cream-dark: #e8e2d5;
  --text-main: #2c3531;
  --text-muted: #62726b;
  --accent: #d97757;
  --border: #d0dcd3;
  --radius: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  padding: 2rem 1rem;
}

.container {
  max-width: 800px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: 2.25rem;
  color: var(--sage-dark);
  margin-bottom: 0.5rem;
  font-weight: 700;
}

header p {
  color: var(--text-muted);
  font-size: 1.05rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: 0 4px 12px rgba(59, 82, 73, 0.05);
  margin-bottom: 2rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}

@media(min-width: 600px) {
  .form-grid {
    grid-template-columns: 1fr 1fr;
  }
  .full-width {
    grid-column: span 2;
  }
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--sage-dark);
}

input {
  padding: 0.75rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
  background: var(--cream);
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--sage-mid);
  box-shadow: 0 0 0 3px var(--sage-light);
}

.btn-row {
  display: flex;
  gap: 1rem;
  margin-top: 1.5rem;
}

button {
  cursor: pointer;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  transition: background 0.2s, transform 0.1s;
}

button:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--sage-dark);
  color: white;
  flex: 1;
}

.btn-primary:hover {
  background: var(--sage-mid);
}

.btn-secondary {
  background: var(--sage-light);
  color: var(--sage-dark);
}

.btn-secondary:hover {
  background: var(--cream-dark);
}

.result-box {
  background: var(--sage-light);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.25rem;
  margin-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.result-box h3 {
  font-size: 0.9rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.result-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--sage-dark);
}

.saved-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.saved-item {
  background: var(--cream);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.saved-details h4 {
  color: var(--sage-dark);
  font-size: 1.1rem;
  margin-bottom: 0.2rem;
}

.saved-details p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.btn-danger {
  background: #fdf2f0;
  color: var(--accent);
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
}

.btn-danger:hover {
  background: #fae2de;
}

.notice {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: center;
  margin-top: 1rem;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

