(async function() {
  let state = await lf.ready;
  const ingredientInput = document.getElementById('ingredient');
  const amountInput = document.getElementById('amount');
  const origServingsInput = document.getElementById('orig-servings');
  const targetServingsInput = document.getElementById('target-servings');
  const calcBtn = document.getElementById('calc-btn');
  const saveBtn = document.getElementById('save-btn');
  const resultContainer = document.getElementById('result-container');
  const resVal = document.getElementById('res-val');
  const statusMsg = document.getElementById('status-msg');
  const savedList = document.getElementById('saved-list');

  let lastCalculation = null;

  function render(currentState) {
    state = currentState;
    const records = state.records || [];

    if (records.length === 0) {
      savedList.innerHTML = '<p class="notice" style="text-align: left;">No saved calculations yet.</p>';
      return;
    }

    savedList.innerHTML = '';
    records.forEach(rec => {
      const vals = rec.values || {};
      const item = document.createElement('div');
      item.className = 'saved-item';

      const details = document.createElement('div');
      details.className = 'saved-details';

      const h4 = document.createElement('h4');
      h4.textContent = vals.ingredient || 'Unnamed Ingredient';

      const p = document.createElement('p');
      p.textContent = `Scaled: ${vals.scaledAmount} (Orig: ${vals.amount} for ${vals.origServings} -> ${vals.targetServings} servings)`;

      details.appendChild(h4);
      details.appendChild(p);

      const delBtn = document.createElement('button');
      delBtn.className = 'btn-danger';
      delBtn.textContent = 'Delete';
      delBtn.addEventListener('click', async () => {
        try {
          const next = await lf.remove(rec.id);
          render(next);
        } catch (err) {
          statusMsg.textContent = 'Failed to delete calculation.';
        }
      });

      item.appendChild(details);
      item.appendChild(delBtn);
      savedList.appendChild(item);
    });
  }

  calcBtn.addEventListener('click', async () => {
    const ingredient = ingredientInput.value.trim();
    const amount = parseFloat(amountInput.value);
    const origServings = parseFloat(origServingsInput.value);
    const targetServings = parseFloat(targetServingsInput.value);

    if (!ingredient || isNaN(amount) || isNaN(origServings) || isNaN(targetServings)) {
      statusMsg.textContent = 'Please fill out all fields with valid numbers.';
      return;
    }

    if (origServings <= 0) {
      statusMsg.textContent = 'Original servings must be positive.';
      return;
    }

    if (!state.preview && !state.permissions?.canUseTools) {
      statusMsg.textContent = 'Publish to run tool.';
      return;
    }

    if (state.preview) {
      statusMsg.textContent = 'Preview only. Publish to save changes / run tools.';
      // Fallback local calc for preview
      const scaled = Math.round((amount / origServings) * targetServings * 100) / 100;
      lastCalculation = { ingredient, amount, origServings, targetServings, scaledAmount: scaled };
      resVal.textContent = scaled;
      resultContainer.style.display = 'flex';
      return;
    }

    statusMsg.textContent = 'Calculating via backend tool...';
    try {
      const response = await lf.runTool('scale_recipe', 1, {
        amount,
        originalServings: origServings,
        targetServings: targetServings
      });

      const scaled = response.result.scaledAmount;
      lastCalculation = { ingredient, amount, origServings, targetServings, scaledAmount: scaled };
      resVal.textContent = scaled;
      resultContainer.style.display = 'flex';
      statusMsg.textContent = 'Calculation complete.';
    } catch (err) {
      statusMsg.textContent = 'Tool invocation failed: ' + (err.message || err);
    }
  });

  saveBtn.addEventListener('click', async () => {
    if (!lastCalculation) return;
    if (state.preview) {
      statusMsg.textContent = 'Preview only. Publish to save changes.';
      return;
    }

    try {
      statusMsg.textContent = 'Saving calculation...';
      const next = await lf.create(lastCalculation);
      render(next);
      statusMsg.textContent = 'Calculation saved successfully.';
    } catch (err) {
      statusMsg.textContent = 'Failed to save calculation.';
    }
  });

  lf.subscribe(render);
  render(state);
  await lf.reportReady();
})().catch(err => {
  console.error(err);
  document.getElementById('status-msg').textContent = 'Initialization error occurred.';
  lf.reportReady();
});

